import { HyperAxisError } from '../error.js';
import type { HyperAxisWasmBindings } from './bindings.js';

/** Loads an initialized HyperAxis WASM binding object. */
export type HyperAxisWasmLoader = () => Promise<HyperAxisWasmBindings>;

/** Inputs supported by wasm-bindgen's async web initializer. */
export type HyperAxisWasmInitInput =
  | BufferSource
  | RequestInfo
  | Response
  | URL
  | WebAssembly.Module;

/** Shape of the ES module generated by wasm-bindgen `--target web`. */
export interface HyperAxisGeneratedWasmModule extends HyperAxisWasmBindings {
  default(
    input?:
      | HyperAxisWasmInitInput
      | Promise<HyperAxisWasmInitInput>
      | {
          readonly module_or_path:
            | HyperAxisWasmInitInput
            | Promise<HyperAxisWasmInitInput>;
        },
  ): Promise<unknown>;
}

/**
 * Creates an idempotent loader for the generated `hyper_axis.js` module.
 *
 * The importer should normally be `() => import('@cryptokango/hyper-axis/wasm')`.
 * [wasmInput] may be a URL, Response, bytes, or WebAssembly.Module accepted by
 * the generated initializer.
 */
export function createHyperAxisWasmLoader(options: {
  readonly importModule: () => Promise<HyperAxisGeneratedWasmModule>;
  readonly wasmInput?: HyperAxisWasmInitInput | Promise<HyperAxisWasmInitInput>;
}): HyperAxisWasmLoader {
  let initialization: Promise<HyperAxisWasmBindings> | undefined;
  return async (): Promise<HyperAxisWasmBindings> => {
    initialization ??= initializeGeneratedModule(options);
    return initialization;
  };
}

async function initializeGeneratedModule(options: {
  readonly importModule: () => Promise<HyperAxisGeneratedWasmModule>;
  readonly wasmInput?: HyperAxisWasmInitInput | Promise<HyperAxisWasmInitInput>;
}): Promise<HyperAxisWasmBindings> {
  try {
    const module = await options.importModule();
    await module.default(
      options.wasmInput === undefined
        ? undefined
        : { module_or_path: options.wasmInput },
    );
    return module;
  } catch (error: unknown) {
    throw new HyperAxisError({
      code: 'initialization',
      message: 'Unable to initialize HyperAxis WebAssembly.',
      operation: 'initializeWasm',
      cause: error,
    });
  }
}

